    "<div class='example'>2.1, ?, ?, 3.0<br>Change: 3.0 - 2.1 = 0.9<br>Jumps: 3<br>0.9 / 3 = 0.3</div>",
    "<p class='text-dim'>Always check <i>two</i> jumps before you decide. One jump can fool you.</p>"
